    encoded_message = ''

    for char in message:
        if char.lower() in vowels:
            if char.islower():
                encoded_message += chr(ord(char) - 32)  # Swap case to uppercase
            else:
                encoded_message += chr(ord(char) + 32)  # Swap case to lowercase
            # Find the corresponding vowel and replace it
            if char.lower() == 'a':
                encoded_message += 'c'
            elif char.lower() == 'e':
                encoded_message += 'g'
            elif char.lower() == 'i':
                encoded_message += 'k'
            elif char.lower() == 'o':
                encoded_message += 'q'
            elif char.lower() == 'u':
                encoded_message += 'w'
        else:
            if char.islower():
                encoded_message += chr(ord(char) - 32)  # Swap case to uppercase
            else:
